import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

export default function Checkout() {
  const initialCart = [
    {
      id: 1,
      name: "Ajwa Dates",
      basePrice: 300,
      image: "https://via.placeholder.com/80",
      quantity: 1,
      weight: "250g",
    },
    {
      id: 2,
      name: "Almonds",
      basePrice: 250,
      image: "https://via.placeholder.com/80",
      quantity: 1,
      weight: "250g",
    },
  ];

  const weightMultiplier = {
    "250g": 1,
    "500g": 2,
    "1kg": 4,
  };

  const [cartItems, setCartItems] = useState(initialCart);

  const handleQuantityChange = (id, value) => {
    setCartItems(
      cartItems.map((item) =>
        item.id === id
          ? { ...item, quantity: Math.max(1, value) }
          : item
      )
    );
  };

  const handleWeightChange = (id, weight) => {
    setCartItems(
      cartItems.map((item) =>
        item.id === id ? { ...item, weight } : item
      )
    );
  };

  const getItemTotal = (item) =>
    item.basePrice *
    weightMultiplier[item.weight] *
    item.quantity;

  const subtotal = cartItems.reduce(
    (sum, item) => sum + getItemTotal(item),
    0
  );

  const shipping = 50;
  const total = subtotal + shipping;

  const handlePayNow = () => {
    alert("Redirecting to secure payment...");
  };

  return (
    <div
      className="py-5"
      style={{
        background: "linear-gradient(135deg, #fdf6ec, #f7efe5)",
      }}
    >
      <div className="container">
        {/* Heading */}
        <div className="text-center mt-5">
          <h2 className="fw-bold text-brown">Checkout 🛒</h2>
          <p className="text-muted">
            Review your selected dry fruits and proceed to payment
          </p>
        </div>

        <div className="row g-4">
          {/* Order Details */}
          <div className="col-lg-8">
            <div className="card border-0 shadow-lg rounded-4">
              <div className="card-body p-4">
                <h5 className="fw-semibold text-brown mb-4">
                  Ordered Products
                </h5>

                {cartItems.map((item) => (
                  <div
                    key={item.id}
                    className="row align-items-center border-bottom py-3"
                  >
                    <div className="col-3 col-md-2">
                      <img
                        src={item.image}
                        alt={item.name}
                        className="img-fluid rounded-3"
                      />
                    </div>

                    <div className="col-9 col-md-4">
                      <h6 className="mb-1">{item.name}</h6>
                      <small className="text-muted">
                        Weight: <strong>{item.weight}</strong>
                      </small>
                    </div>

                    <div className="col-md-2 mt-2 mt-md-0">
                      <select
                        className="form-select rounded-3"
                        value={item.weight}
                        onChange={(e) =>
                          handleWeightChange(
                            item.id,
                            e.target.value
                          )
                        }
                      >
                        <option value="250g">250g</option>
                        <option value="500g">500g</option>
                        <option value="1kg">1kg</option>
                      </select>
                    </div>

                    <div className="col-md-2 mt-2 mt-md-0">
                      <input
                        type="number"
                        min="1"
                        className="form-control rounded-3"
                        value={item.quantity}
                        onChange={(e) =>
                          handleQuantityChange(
                            item.id,
                            e.target.value
                          )
                        }
                      />
                    </div>

                    <div className="col-md-2 text-end mt-2 mt-md-0">
                      <strong>₹{getItemTotal(item)}</strong>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Price Summary */}
          <div className="col-lg-4">
            <div className="card border-0 shadow-lg rounded-4 sticky-top">
              <div
                className="card-body p-4 text-white"
                style={{
                  background:
                    "linear-gradient(135deg, #8b5e3c, #a47148)",
                  borderRadius: "1rem",
                }}
              >
                <h5 className="fw-semibold mb-4">
                  Price Summary
                </h5>

                <div className="d-flex justify-content-between mb-2">
                  <span>Subtotal</span>
                  <span>₹{subtotal}</span>
                </div>

                <div className="d-flex justify-content-between mb-2">
                  <span>Shipping</span>
                  <span>₹{shipping}</span>
                </div>

                <hr className="border-light" />

                <div className="d-flex justify-content-between mb-4">
                  <strong>Total</strong>
                  <strong>₹{total}</strong>
                </div>

                <button
                  className="btn w-100 fw-semibold rounded-3"
                  style={{
                    backgroundColor: "#fff",
                    color: "#8b5e3c",
                  }}
                  onClick={handlePayNow}
                >
                  Pay Now
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Theme Styles */}
      <style>
        {`
          .text-brown {
            color: #8b5e3c;
          }

          .form-control:focus,
          .form-select:focus {
            border-color: #8b5e3c;
            box-shadow: 0 0 0 0.2rem rgba(139, 94, 60, 0.25);
          }

          .card:hover {
            transform: translateY(-4px);
            transition: all 0.3s ease;
          }
        `}
      </style>
    </div>
  );
}
